def _digest(text):
    return base64.b64encode(hashlib.sha256(text.encode()).digest()).decode()


def content_security_policy():
    return (
        "default-src 'none'; script-src 'sha256-"
        + _digest(_SCRIPT)
        + "'; style-src 'sha256-"
        + _digest(_STYLE)
        + "'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    )


def render():
    """Only application code is embedded; trace labels arrive as JSON data."""
    return _BODY.replace("STYLE", _STYLE).replace("SCRIPT", _SCRIPT).encode("utf-8")
